${params.warehouseScope}

mapper.select:
select
    ifnull(sum(s.quantity), 0) as total_quantity,
    ifnull(sum(s.quantity * coalesce(nullif(ca.avg_cost, 0), p.cost_price, 0)), 0) as total_amount
from (
    select warehouse_id, product_id, quantity
    from wms_stock
    where 1 = 1

        and warehouse_id = #{warehouseId}

    ${params.warehouseScope}
) s
left join md_product p on s.product_id = p.product_id
left join fin_cost_account ca on ca.product_id = s.product_id and ca.warehouse_id = s.warehouse_id
     and ca.cost_method = coalesce(#{params.costMethod}, 'moving')

select s.product_id as product_id, max(p.product_code) as product_code, max(p.product_name) as product_name, max(p.unit_name) as unit_name, ifnull(sum(s.quantity - ifnull(s.locked_quantity, 0) - ifnull(s.frozen_quantity, 0)), 0) as available_quantity, ifnull(sum(s.quantity * coalesce(nullif(ca.avg_cost, 0), p.cost_price, 0)), 0) as stock_amount from ( select warehouse_id, product_id, quantity, locked_quantity, frozen_quantity from wms_stock where 1 = 1
and warehouse_id = #{warehouseId}
${params.warehouseScope} ) s left join md_product p on s.product_id = p.product_id left join fin_cost_account ca on ca.product_id = s.product_id and ca.warehouse_id = s.warehouse_id and ca.cost_method = coalesce(#{params.costMethod}, 'moving') group by s.product_id order by available_quantity desc limit #{rankLimit}
